        int ans = 0;
        int l = 0, r = s.size() - 1;
        while (l < r) {
            int k = r;
            while (k > l && s[k] != s[l]) {
                k--;
            }
            if (k == l) {
                ans += (int)s.size() / 2 - l;
                l++;
            } else {
