class Solution {
    public int minMovesToMakePalindrome(String s) {
        char[] arr = s.toCharArray();
        int ans = 0;
        int l = 0, r = arr.length - 1;
        while (l < r) {
            int k = r;
            while (k > l && arr[k] != arr[l]) {
                k--;
            }
            if (k == l) {
                ans += arr.length / 2 - l;
                l++;
            } else {
                while (k < r) {
                    char temp = arr[k];
                    arr[k] = arr[k + 1];
                    arr[k + 1] = temp;
                    ans++;
                    k++;
                }
                l++;
                r--;
            }
        }
        return ans;
    }
}

