var minMovesToMakePalindrome = function(s) {
    const arr = s.split('');
    let ans = 0;
    let l = 0, r = arr.length - 1;
    while (l < r) {
        let k = r;
        while (k > l && arr[k] !== arr[l]) {
            k--;
        }
        if (k === l) {
            ans += Math.floor(arr.length / 2) - l;
            l++;
        } else {
            while (k < r) {
                const temp = arr[k];
                arr[k] = arr[k + 1];
                arr[k + 1] = temp;
                ans++;
                k++;
            }
            l++;
            r--;
        }
    }
    return ans;
};
